  "explanation": "„Triada letală” include hipotermia, acidoza și coagulopatia — Corect: Cele trei componente ale triadei letale sunt enumerate explicit.\n\nChirurgia de control lezional durează, de obicei, între 60 și 90 de minute, urmată de resuscitare în terapie intensivă — Corect: Intervalul 60–90 de minute este citat pentru durata intervenției de control lezional.\n\nDupă aproximativ 12–48 de ore, pacientul revine în sală pentru reconstrucție digestivă și îndepărtarea câmpurilor — Corect: Reintervenția la 12–48 de ore este descrisă după stabilizare.\n\nSindromul de compartiment abdominal se suspectează când presiunea intra-abdominală depășește 25 mmHg și asociază insuficiență de organ — Corect: Pragul de peste 25 mmHg plus insuficiență de organ definește suspiciunea de SCA.\n\nDiagnosticul se bazează pe măsurarea presiunii în vena cavă inferioară, nu pe presiunea vezicală — Incorect: Presiunea vezicală corespunde indirect presiunii intraperitoneale; nu vena cavă este metoda descrisă.\n\nReferință: Lawrence, Chirurgie generală și specialități chirurgicale, ediția pentru rezidențiat MG 2025, cap. 9, p. 101, 100, Controlul lezional — Sindromul de compartiment abdominal (pagini PDF: 44, 43).",
