  "explanation": "Venele cerebrale care ajung în sinusurile durei pot fi rupte în traumatisme închise, producând hemoragie subdurală — Corect: Ruptura venelor cerebrale către sinusuri este mecanismul subdural descris.\n\nArtera meningeală, situată între craniu și dura, poate fi lezată de fracturi temporale sau parietale, producând hematoame epidurale — Corect: Poziția arterei meningee între craniu și dura și fracturile temporo-parietale sunt explicite.\n\nPia mater acoperă direct creierul; leziunile vaselor de la acest nivel pot cauza hemoragie subarahnoidiană sau contuzie intraparenchimatoasă — Corect: Rolul piei mater în HSA/contuzie este citat.\n\nArtera meningeală traversează spațiul subarahnoidian, deci fractura temporală produce doar hemoragie subarahnoidiană — Incorect: Artera meningeală nu este subarahnoidiană; fractura temporală orientează spre epidural.\n\nDura nu formează sinusuri venoase, falx sau cortul cerebelului — Incorect: Dura formează sinusurile, falx cerebri/cerebelli, diafragma șeii și cortul cerebelului.\n\nReferință: Lawrence, Chirurgie generală și specialități chirurgicale, ediția pentru rezidențiat MG 2025, cap. 9, p. 89, Traumatisme cranio-cerebrale — Anatomie meningeală (pagini PDF: 32).",
