  "explanation": "Angiografia CT are sensibilitate aproape de 100% și valoare predictivă negativă de peste 90% — Corect: Sensibilitatea aproape 100% și VPN peste 90% sunt explicite.\n\nO limitare recunoscută a CT-ului este dificultatea de a determina traiectul leziunilor produse de cuțite, în special a leziunilor faringo-esofagiene mici — Corect: Limitarea traiectului de cuțit și a leziunilor faringo-esofagiene mici este citată.\n\nZonele I și III, la stabil, se abordează selectiv din cauza dificultății de expunere chirurgicală — Corect: Abordarea selectivă a zonelor I și III la stabil este descrisă.\n\nCT-ul are sensibilitate sub 50% și a fost abandonat în favoarea explorării de principiu a zonei II — Incorect: Literatura susține creșterea rolului CT la stabili, nu abandonul.\n\nLeziunile prin cuțit sunt cele mai ușor de cartografiat pe CT, față de proiectile — Incorect: Dificultatea de traiect este tocmai a cuțitelor, nu ușurința.\n\nReferință: Lawrence, Chirurgie generală și specialități chirurgicale, ediția pentru rezidențiat MG 2025, cap. 9, p. 103, 102, Gât penetrant — CT angiografie (pagini PDF: 46, 45).",
