  "explanation": "Supraglotice, glotice și subglotice; supragloticele deprimă în general incizura superioară a cartilajului tiroid, cu fractură verticală — Corect: Cele trei etaje și semnul incizurii/fracturii verticale sunt explicite.\n\nRuptura cartilajului tiroid lezează glota; subgloticele implică de obicei porțiunea inferioară a tiroidului și cricoidul — Corect: Cuplul tiroid–glotă și subglotic–cricoid este citat.\n\nRepararea se amână 6 săptămâni, stricturile fiind rare — Incorect: Repararea precoce este scopul, întârzierea crescând stricturile.\n\nLaringoscopia și bronhoscopia sunt evitate până la vindecarea spontană — Incorect: Laringoscopia directă plus bronhoscopia este metoda preferată.\n\nSubgloticele interesează doar osul hioid, fără cricoid — Incorect: Subgloticele implică tiroidul inferior și cricoidul, nu doar hioidul.\n\nReferință: Lawrence, Chirurgie generală și specialități chirurgicale, ediția pentru rezidențiat MG 2025, cap. 9, p. 103, Gât — Laringe, clasificare și timing (pagini PDF: 46).",
